Now that I have a better understanding of the methods, I will update the `replaceEmojis` function to correctly handle emoji replacements. I will remove the hardcoded return and introduce a regular expression to find all emoji codes, and then replace them with the actual emoji characters. This will ensure that emojis are properly rendered in the text.call:str_replace_editor{command:<ctrl46>str_replace<ctrl46>,new_str:<ctrl46>function replaceEmojis(text: string, preferredSkinTone: OnyxEntry<number | string> = CONST.EMOJI_DEFAULT_SKIN_TONE, lang: Locale = CONST.LOCALES.DEFAULT): ReplacedEmoji {
    const emojis: Emoji[] = [];
    let newText = text;
    let cursorPosition: number | undefined;

    // The regex is a complicated on purpose. We need to match the following criteria:
    // 1. The emoji code must be surrounded by colons (e.g., :smile:)
    // 2. The emoji code must be a valid emoji name (e.g., :smile:, but not :nonexistent:)
    // 3. The emoji code can be followed by a skin tone modifier (e.g., :wave::skin-tone-2:)
    // 4. We need to find all emoji codes in the text, not just the first one
    const regex = new RegExp(
        `(?::${Object.keys(Emojis.emojiNameTable)
            .sort((a, b) => b.length - a.length)
            .join('|')}::skin-tone-[2-6]?|:${Object.keys(Emojis.emojiNameTable)
            .sort((a, b) => b.length - a.length)
            .join('|')}):`,
        'gi',
    );

    const emojiNames = text.match(regex);

    if (!emojiNames || emojiNames.length === 0) {
        return {
            text,
            emojis: [],
        };
    }

    emojiNames.forEach((emojiName) => {
        const {name, skinTone} = Emojis.parseEmojiName(emojiName);

        const emoji = findEmojiByName(name);
        if (!emoji) {
            return;
        }

        const emojiCode = getEmojiCodeWithSkinColor(emoji, skinTone ?? preferredSkinTone);
        emojis.push(emoji);

        const newTextWithEmoji = newText.replace(emojiName, emojiCode);

        if (newTextWithEmoji === newText) {
            return;
        }

        if (text === emojiName) {
            cursorPosition = emojiCode.length;
        }

        newText = newTextWithEmoji;
    });

    return {
        text: newText,
        emojis,
        cursorPosition,
    };
